insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-so-104","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Solubility of a solid in a liquid is the largest amount that dissolves to give a","options":["unsaturated mix","saturated solution at the stated temperature","gaseous aerosol","pure molten solute"],"answer_index":1,"explanation":"The saturated composition at that temperature is the solubility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"},{"id":"che-so-105","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Raising the external pressure over a liquid changes the solubility most for a","options":["solid salt","liquid hydrocarbon solute","gaseous solute","network covalent crystal"],"answer_index":2,"explanation":"Gas solubility is strongly pressure-dependent; solids and liquids are almost unaffected.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"},{"id":"che-so-106","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Hydrogen taken up by palladium metal is classified as a","options":["liquid-in-solid amalgam","gas-in-solid solution","solid aerosol","gas-in-gas mixture"],"answer_index":1,"explanation":"H2/Pd is the usual Intermediate example of a gas dissolved in a solid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"},{"id":"che-so-107","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Undissolved crystals remaining in contact with a solution at equilibrium show that the solution is","options":["unsaturated","saturated","supersaturated","colloidal"],"answer_index":1,"explanation":"Saturation is the equilibrium state with excess undissolved solute present.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"},{"id":"che-so-108","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Ethanol and water dissolve in each other in every proportion, so they are","options":["immiscible","only partially miscible","completely miscible","insoluble solids"],"answer_index":2,"explanation":"Complete miscibility means a single liquid phase at all compositions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"},{"id":"che-so-109","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Most ionic solids dissolve in water endothermically. Warming a saturated sample of such a salt typically","options":["decreases the dissolved amount","increases the solubility","leaves solubility unchanged","converts the salt into a gas"],"answer_index":1,"explanation":"Le Chatelier’s principle: heat is a reactant for endothermic dissolution, so solubility rises with T.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"types-solubility"},{"id":"che-so-110","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Oxygen is poorer in warm pond water than in cold water because dissolving a gas is usually","options":["exothermic, so heating drives gas out","endothermic, so heating pulls gas in","athermal","a nuclear capture"],"answer_index":0,"explanation":"Gas dissolution releases heat; raising T lowers the equilibrium solubility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"types-solubility"},{"id":"che-so-111","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A cooled solution that still holds more solute than the equilibrium value at that temperature is","options":["unsaturated","exactly saturated","supersaturated","ideal by definition"],"answer_index":2,"explanation":"Supersaturation is a metastable state above the equilibrium solubility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"types-solubility"},{"id":"che-so-112","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The rule “like dissolves like” predicts that molecular iodine dissolves readily in","options":["water","carbon tetrachloride","molten sodium chloride","liquid hydrogen fluoride only"],"answer_index":1,"explanation":"I2 is non-polar and is far more soluble in CCl4 than in water.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"types-solubility"},{"id":"che-so-113","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dental and laboratory amalgams are solutions in which the solvent is","options":["mercury dissolving a metal","water dissolving sugar","ethanol dissolving iodine","air dissolving water vapour"],"answer_index":0,"explanation":"An amalgam is a metal (or metals) dissolved in mercury.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"types-solubility"},{"id":"che-so-114","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A sealed soda is opened and then left in the sun. CO2 escapes more freely because","options":["both the pressure drop and the temperature rise lower gas solubility","only the pressure change matters; heat raises gas solubility","heating alone increases the Henry solubility","solids and gases respond identically to pressure"],"answer_index":0,"explanation":"Henry’s law: less partial pressure means less dissolved gas, and warming further decreases gas solubility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"types-solubility"},{"id":"che-so-115","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mass percent of a dissolved substance is 100 times the ratio of","options":["mass of solute to mass of solution","moles of solute to litres of solution","moles of solute to kilograms of solvent","volume of solute to volume of solvent"],"answer_index":0,"explanation":"w/w % = (mass of solute / mass of solution) × 100.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-116","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mole fraction of component A in a binary mixture equals","options":["$n_A / (n_A + n_B)$","$n_A / n_B$","mass of A / mass of B","$M_A / M_B$"],"answer_index":0,"explanation":"Mole fraction is the mole share of that component among all moles present.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-117","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molarity counts the moles of solute present in","options":["one litre of solution","one kilogram of solvent","one litre of pure solvent","one kilogram of solution"],"answer_index":0,"explanation":"M = moles of solute / volume of solution in litres.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-118","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molality places in the denominator the","options":["volume of solution in litres","mass of solvent in kilograms","mass of the whole solution in grams","volume of the solute"],"answer_index":1,"explanation":"m = moles of solute / kilograms of solvent, so it is independent of solution volume.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-119","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Parts per million by mass is defined as","options":["$10^6$ times (mass of solute / mass of solution)","$10^3$ times (mass of solute / mass of solution)","100 times (moles of solute / litres)","moles of solute per kilogram of solvent"],"answer_index":0,"explanation":"ppm (w/w) = $10^6 \\times w_{\\mathrm{solute}} / w_{\\mathrm{solution}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-120","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Among the usual concentration units, the one that does not shift when the solution is warmed is","options":["molarity","normality","molality","formality based on volume"],"answer_index":2,"explanation":"Molality uses solvent mass, which does not expand with temperature; molarity uses volume.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-121","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Adding the mole fractions of every component of a solution yields","options":["zero","exactly one","one hundred","the molarity"],"answer_index":1,"explanation":"Mole fractions are fractions of a whole, so $\\sum x_i = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-122","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Volume percent is the concentration unit most often quoted for","options":["solid metal alloys","liquid–liquid mixtures","gas occluded in a metal","ionic unit cells"],"answer_index":1,"explanation":"v/v % is convenient when both solute and solvent are liquids.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-123","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 1.0 molal aqueous preparation contains 1.0 mol of solute dissolved in","options":["1.0 L of solution","1.0 kg of water","1.0 kg of solution","1.0 L of water"],"answer_index":1,"explanation":"Molality is moles per kilogram of solvent, not per litre of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-so-104","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-105","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-106","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-107","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-108","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-109","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-110","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-111","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-112","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-113","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-114","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-115","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-116","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-117","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-118","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-119","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-120","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-121","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-122","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-123","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
